-- V35__seed_pilot_area_gaya_ghaziabad.sql
-- Real LGD reference data for the two pilot districts, so the location
-- flow works out of the box:
--   * all 36 states and all districts of India (to recognise ANY address,
--     and to flag complaints from districts this deployment does not serve);
--   * for Gaya (Bihar, LGD 196) and Ghaziabad (Uttar Pradesh, LGD 145):
--     sub-districts, blocks, revenue villages, Gram Panchayats, urban local
--     bodies and the village -> Gram Panchayat / urban body links;
--   * both districts marked is_served = TRUE.
-- Example chain: village "Jolah Bigha" (Gurua) -> Gram Panchayat "Pakri";
-- "Jolah Bigha" (Tikari) -> "Tekari" Municipality.
--
-- Generated with database/tools/lgd_import/lgd_import.py --flyway from the
-- LGD snapshot of 11 March 2022 (github.com/planemad/india-local-government-directory,
-- Government Open Data License - India). NOT included: wards and PIN codes
-- (not in that snapshot). Load a current LGD download (wards of urban/rural
-- bodies) and the India Post PIN directory with the same tool - see
-- database/tools/lgd_import/README.md. Re-running the tool only UPDATES
-- these rows (LGD codes are primary keys), so this migration never conflicts
-- with a newer import.
-- Generated by database/tools/lgd_import/lgd_import.py on 2026-10-11
-- Districts: [145, 196]; source date 2022-03-11
